"""Capabilities supplied by hosts. No database connection or business Store escapes here."""
from pathlib import Path
from typing import Protocol

class MaterialPort(Protocol):
    def review_asset_url(self, ident: str, asset: str) -> str: ...
    def twin_source(self, ident: str, asset: str) -> Path: ...
    def write_twin_source(self, ident: str, claim: str, asset: str, raw: bytes) -> Path: ...

class TaskPort(MaterialPort, Protocol):
    def task_snapshot(self, ident: str) -> tuple[dict, dict | None]: ...
    def twin_index(self) -> dict: ...
    def start_twin(self, body: dict) -> dict: ...
    def confirm_twin(self, ident: str, release: str, configured: bool) -> dict: ...
    def claim_twin(self, owner: str) -> dict | None: ...
    def heartbeat_twin(self, ident: str, claim: str) -> bool: ...
    def update_twin(self, ident: str, claim: str, **patch) -> bool: ...
    def cancel_twin(self, ident: str) -> dict: ...
    def set_twin_accessories(self, ident: str, selected: list, downloaded: dict) -> dict: ...

class CatalogPort(Protocol):
    def get(self, path: str, params: dict) -> dict: ...

class VisionPort(Protocol):
    def public_config(self) -> dict: ...
    def agent_json(self, system: str, prompt: str, images=(), on_start=None) -> dict: ...
